#!/usr/bin/env bash
#
# PreToolUse hook (Edit|Write|MultiEdit): CLAUDE.md and AGENTS.md are generated by Laravel Boost
# from .ai/guidelines/*.md; a manual edit is overwritten by the next `composer ai:update`.
#
set -euo pipefail
. "$(dirname "${BASH_SOURCE[0]}")/_lib.sh"
hook_read_input

case "$(hook_field tool_input.file_path)" in
  */CLAUDE.md | CLAUDE.md | */AGENTS.md | AGENTS.md)
    hook_block "CLAUDE.md and AGENTS.md are generated by Laravel Boost." \
      "Edit the matching file in .ai/guidelines/*.md, then run: composer ai:update"
    ;;
esac

exit 0
